// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 delay) public {
        delay = bound(delay, 1, 365 days);

        vm.roll(1);
        vm.warp(1000);

        uint256 val = 10 ether;
        address actor = address(0x1234);
        vm.deal(actor, val * 2);

        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: val}("");
        require(ok1, "first call failed");

        vm.warp(1000 + delay);
        vm.roll(2);

        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: val}("");
        require(ok2, "second call failed");

        assertEq(c.pastBlockTime(), 1000 + delay);
    }
}
